#include "Plugin.hpp"

#include "SKSE/SKSE.h"

// This translation unit contains exactly one function. The plugin declaration — name,
// version, author, runtime compatibility, minimum SKSE version — is generated by CMake
// via add_commonlibsse_plugin() (see CMakeLists.txt), so the version cannot drift
// between the build system and the binary, and this repository contains no hand-written
// metadata to forget to update. That is the entire ceremony. The rest of the plugin is
// in src/, doing nothing.

SKSEPluginLoad(const SKSE::LoadInterface* a_skse) { return pef::LoadPlugin(*a_skse); }
